//! History contains only notifications actually accepted by the native process.
use crate::{widgets::Ui,model::{Model,Page,Action},draw::{rect,Icon}};
use serde_json::{json,Value};
fn pause(ui:&mut Ui,m:&Model,x:f64,y:f64,w:f64){let paused=m.setting("PauseNotifications").as_bool().unwrap_or(false);ui.button(rect(x,y,w,40.),if paused{"恢复通知"}else{"暂停通知"},Some(if paused{Icon::Play}else{Icon::Pause}),Action::NativeEdit("PauseNotifications",json!(!paused)),true,true);}
pub fn overview(ui:&mut Ui,m:&Model,x:f64,y:f64,w:f64)->f64{
 let s=ui.s;ui.panel(rect(x,y,w,272.),s.container);ui.icon(Icon::Volume,x+26.,y+25.,24.,s.primary);ui.label("通知中心",x+66.,y+23.,22.,s.on_surface,true,w-400.);pause(ui,m,x+w-280.,y+20.,122.);ui.button(rect(x+w-146.,y+20.,120.,40.),"查看全部",None,Action::Navigate(Page::Notifications),true,true);
 let events=m.native_state["notificationHistory"].as_array();if events.is_none_or(|a|a.is_empty()){ui.label("此刻很安静",x+28.,y+107.,22.,s.on_surface,true,w-56.);ui.label("点屿收到的通知和到期提醒，会收拢在这里。",x+28.,y+151.,13.,s.on_surface_variant,false,w-56.);}else{for(i,event)in events.unwrap().iter().take(2).enumerate(){row(ui,event,x+12.,y+75.+i as f64*88.,w-24.,false);}}
 y+272.
}
pub fn deck(ui:&mut Ui,m:&Model,x:f64,y:f64,w:f64,h:f64){let s=ui.s;pause(ui,m,x+26.,y,w.min(136.));ui.button(rect(x+w-156.,y,130.,40.),"查看全部",None,Action::Navigate(Page::Notifications),true,true);let events=m.native_state["notificationHistory"].as_array();if events.is_none_or(|a|a.is_empty()){ui.label("此刻很安静",x+28.,y+66.,24.,s.on_surface,true,w-56.);ui.label("点屿收到的通知和到期提醒，会收拢在这里。",x+28.,y+111.,13.,s.on_surface_variant,false,w-56.);}else{for(i,event)in events.unwrap().iter().take(if h<240.{1}else{2}).enumerate(){row(ui,event,x+12.,y+54.+i as f64*88.,w-24.,false);}}}
fn row(ui:&mut Ui,event:&Value,x:f64,y:f64,w:f64,panel:bool){let s=ui.s;if panel{ui.panel(rect(x,y,w,104.),s.container);}ui.label(event["title"].as_str().unwrap_or("通知"),x+24.,y+9.,16.,s.on_surface,true,w-204.);ui.label(event["body"].as_str().unwrap_or(""),x+24.,y+38.,12.,s.on_surface_variant,false,w-204.);ui.label(&format!("{} · {} {}",event["appName"].as_str().unwrap_or("点屿"),event["date"].as_str().unwrap_or(""),event["clock"].as_str().unwrap_or("")),x+24.,y+65.,11.,s.on_surface_variant,false,w-204.);if event["kind"]=="notice"{ui.button(rect(x+w-156.,y+25.,132.,40.),"打开来源",Some(Icon::Arrow),Action::NativeCommand("historyOpen",event["id"].clone()),true,true);}else if let Some(id)=event["todoId"].as_str(){ui.button(rect(x+w-156.,y+25.,132.,40.),"查看待办",None,Action::EditTodo(Some(id.to_owned())),true,true);}}
pub fn render(ui:&mut Ui,m:&Model,x:f64,mut y:f64,w:f64)->f64{
 let s=ui.s;pause(ui,m,x,y,132.);ui.button(rect(x+144.,y,132.,40.),"通知设置",Some(Icon::Settings),Action::SettingsTab(242),true,true);let events=m.native_state["notificationHistory"].as_array();ui.button(rect(x+w-144.,y,144.,40.),"清理记录",Some(Icon::Trash),Action::NativeCommand("historyClear",Value::Null),true,events.is_some_and(|a|!a.is_empty()));y+=56.;
 let cw=(w-32.)/5.;for(i,label)in ["全部","应用通知","待办","计时","设备"].iter().enumerate(){ui.chip(rect(x+i as f64*(cw+8.),y,cw,40.),label,m.notice_filter==i as u8,Action::NoticeFilter(i as u8));}y+=56.;
 let access=m.native_state["notificationState"]["access"].as_str().unwrap_or("unknown");if access!="granted"&&access!="allowed"{let detail=m.native_state["notificationState"]["message"].as_str().unwrap_or("连接后显示 Windows 通知访问状态");ui.panel(rect(x,y,w,72.),s.high);ui.label(detail,x+22.,y+23.,13.,s.on_surface_variant,false,w-44.);y+=90.;}
 let kind=["","notice","todo","timer","device"][m.notice_filter.min(4)as usize];let mut count=0;
 if let Some(events)=events{for event in events.iter().filter(|e|kind.is_empty()||e["kind"]==kind){row(ui,event,x,y,w,true);y+=120.;count+=1;}}
 if count==0{ui.panel(rect(x,y,w,212.),s.container);ui.icon(Icon::Volume,x+26.,y+28.,30.,s.primary);ui.label("暂时没有这类通知",x+26.,y+88.,24.,s.on_surface,true,w-52.);ui.label("新收到的通知会自动出现在这里。",x+26.,y+140.,13.,s.on_surface_variant,false,w-52.);y+=232.;}
 if let Some(e)=m.native_state["historyError"].as_str(){ui.label(e,x+4.,y,13.,s.error,false,w-8.);y+=44.;}y
}
